sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var childAggregated = new GlideRecord('x_hsb11_hsbcmss_eh_aggregated_trade_email_queue'); //MSSRBXSN-2705: Check on associated Child Aggregated Trade Email Queue record fields  before QTRACK AGENT TASK closure
    childAggregated.addQuery('trade_case_task', current.sys_id);
    childAggregated.query();
    if (childAggregated.next()) {
        if ((childAggregated.trade_status == 'Trade confirmed') && (childAggregated.stock_connect_trade == '' || childAggregated.block_trade_id == '' || childAggregated.trade_date == '' || childAggregated.value_date == '' || childAggregated.direction == '' || childAggregated.gross_price == '' || childAggregated.instrument_id == '')) {
            current.setAbortAction(true);
            gs.addErrorMessage('Please check QTRACK required field values on related Child Aggregated Trade Email Queue record before closing this task');
        } else if ((childAggregated.trade_status == 'Trade Mismatch') && (childAggregated.stock_connect_trade == '' || childAggregated.block_trade_id == '' || childAggregated.trade_date == '' || childAggregated.value_date == '' || childAggregated.direction == '' || childAggregated.gross_price == '' || childAggregated.ric_isin == '' || childAggregated.quantity == '' || childAggregated.mismatched_fields == '' || childAggregated.hsbc_value == '' || childAggregated.cpty_value == '')) {
            current.setAbortAction(true);
            gs.addErrorMessage('Please check QTRACK required field values on related Child Aggregated Trade Email Queue record before closing this task');
        } else if ((childAggregated.trade_status == 'Allocation Trade Mismatch') && (childAggregated.stock_connect_trade == '' || childAggregated.allocation_id == '' || childAggregated.block_trade_id == '' || childAggregated.trade_date == '' || childAggregated.value_date == '' || childAggregated.direction == '' || childAggregated.gross_price == '' || childAggregated.ric_isin == '' || childAggregated.quantity == '' || childAggregated.mismatched_fields == '' || childAggregated.hsbc_value == '' || childAggregated.cpty_value == '' || childAggregated.fund_id_alert_code == '')) {
            current.setAbortAction(true);
            gs.addErrorMessage('Please check QTRACK required field values on related Child Aggregated Trade Email Queue record before closing this task');
        } else if ((childAggregated.trade_status == 'Trade Unmatched' || childAggregated.trade_status == 'Trade Matched' || childAggregated.trade_status == 'Trade Affirmed') && (childAggregated.block_trade_id == '' || childAggregated.trade_date == '' || childAggregated.value_date == '' || childAggregated.direction == '' || childAggregated.gross_price == '' || childAggregated.ric_isin == '' )) {
            current.setAbortAction(true);
            gs.addErrorMessage('Please check QTRACK required field values on related Child Aggregated Trade Email Queue record before closing this task');
        }
    }
})(current, previous);
